{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C34"],
      "claim": "Rufinamide, a carboxamide-substituted azole, has an absolute oral bioavailability of 85% in humans, supporting high oral bioavailability for the query's carboxamide azole riboside.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Emtricitabine, a polar nucleoside analogue, has a mean absolute oral bioavailability of 93% in humans, demonstrating that nucleoside-like polar molecules can be highly bioavailable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C71"],
      "claim": "Lamivudine, another nucleoside analogue, has an absolute oral bioavailability of 86–88% in adults, well above the 20% threshold and supportive for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Zidovudine, a ribose-derived nucleoside, has an absolute oral bioavailability of about 60% in humans, supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Stavudine, a nucleoside analogue, shows absolute oral bioavailability of 61–78% in children, supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C68"],
      "claim": "Didanosine can show low oral bioavailability (14% in children), but this is largely due to acid-catalyzed degradation and formulation sensitivity, which are not expected for the query's full ribose imidazole carboxamide structure.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer nucleoside analogues with polar ribose-like scaffolds show absolute oral bioavailability of 60–93%, well above the 20% threshold. The query's full ribose and carboxamide imidazole structure is consistent with transporter-mediated absorption and good oral bioavailability. Low didanosine values reflect acid lability and formulation issues rather than a general nucleoside limitation.",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability measurement exists for the exact query molecule.",
    "Didanosine low-bioavailability records are confounded by acid lability and formulation dependence.",
    "Pediatric bioavailability values vary more than adult values for several nucleoside analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

